<template>
  <div class="admin-page"><router-link to="/admin" class="back-link">← 返回后台</router-link><div class="page-title">管理员管理</div>
    <div class="card" style="margin-bottom:8px;padding:12px;"><div style="font-weight:700;margin-bottom:8px;font-size:13px;">创建管理员</div><div style="display:flex;gap:6px;flex-wrap:wrap;"><input v-model="newAdminUser" class="input" placeholder="账号" style="flex:1;min-width:100px;" /><input v-model="newAdminPwd" class="input" placeholder="密码" style="flex:1;min-width:100px;" /><button class="btn btn-primary btn-sm" @click="createAdmin">创建</button></div></div>
    <div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>账号</th><th>角色</th><th>创建</th><th>操作</th></tr></thead><tbody><tr v-for="a in store.adminAccounts" :key="a.id"><td style="font-weight:600;">{{ a.username }}</td><td>{{ a.role==='super_admin'?'超级管理员':'普通管理员' }}</td><td style="font-size:11px;color:var(--text-muted);">{{ store.formatDate(a.created_at) }}</td><td><button v-if="a.role!=='super_admin'" class="btn btn-danger btn-xs" @click="doDelete(a.id)">删除</button><span v-else style="font-size:11px;color:var(--text-muted);">—</span></td></tr></tbody></table></div></div>
  </div>
</template>
<script setup>import { ref, inject, onMounted } from 'vue'; import { useAppStore } from '../stores/app'; const store = useAppStore(); const showToast = inject('showToast'); const newAdminUser = ref(''); const newAdminPwd = ref(''); async function createAdmin(){if(!newAdminUser.value||!newAdminPwd.value){showToast('请填写账号密码','error');return}try{await store.createAdmin(newAdminUser.value,newAdminPwd.value);showToast('管理员创建成功');newAdminUser.value='';newAdminPwd.value=''}catch(e){showToast(e.response?.data?.error||'创建失败','error')}} async function doDelete(id){try{await store.deleteAdmin(id);showToast('管理员已删除')}catch(e){showToast(e.response?.data?.error||'删除失败','error')}}; onMounted(async()=>{await store.fetchAdminAccounts()})</script>